    <div className="rounded-3xl bg-zinc-50 p-4 dark:bg-zinc-900/60"><label className="flex items-center gap-2 text-sm font-black"><input type="checkbox" checked={Boolean(form.buildEnabled)} onChange={(e)=>setField("buildEnabled",e.target.checked)}/> Add a Build challenge</label>{form.buildEnabled&&<div className="mt-4 grid gap-3"><input value={form.buildTitle||""} onChange={(e)=>setField("buildTitle",e.target.value)} placeholder="Build challenge title" className="h-11 rounded-2xl border-0 bg-white px-4 text-sm dark:bg-zinc-950"/><textarea rows={3} value={form.buildDescription||""} onChange={(e)=>setField("buildDescription",e.target.value)} placeholder="What should the learner build?" className="rounded-2xl border-0 bg-white px-4 py-3 text-sm dark:bg-zinc-950"/><textarea rows={4} value={form.buildRequirements||""} onChange={(e)=>setField("buildRequirements",e.target.value)} placeholder="One requirement per line" className="rounded-2xl border-0 bg-white px-4 py-3 text-sm dark:bg-zinc-950"/><input type="number" min="0" value={form.buildEstimatedMinutes||0} onChange={(e)=>setField("buildEstimatedMinutes",Number(e.target.value)||0)} className="h-10 w-32 rounded-xl border-0 bg-white px-3 dark:bg-zinc-950"/></div>}</div>
